  it("rebindSession：未知态不发 POST，已知 cwd 时 POST 且 body 恰为该 cwd（#1028 回归）", async () => {
    okFetch();
    const unknown = makeState(undefined, false);
    await rebindSession(unknown as never);
    expect(fetchCalls()).toEqual([]);

    const known = makeState("/a");
    await rebindSession(known as never);
    expect(fetchCalls()).toEqual([SESSION_PATH]);
    expect(fetchBodies()[0]).toContain('"/a"');
  });

  it("已知 blank 会话（行存在但无 cwd）显式上报空串防串台（#1028 回归）", async () => {
    okFetch();
    const ctx = {
      sessions: { list: { getSnapshot: () => listWith({ blank: true }) } },
    } as unknown as McpClientContext;
    const state = makeState("/a");
    const actions = makeActions();
    bindSession(ctx, state as never, actions as never);
    await new Promise((r) => setTimeout(r, 0));
    expect(state.sessionResolved).toBe(true);
    expect(fetchCalls()).toEqual([SESSION_PATH]);
    expect(fetchBodies()[0]).toContain('"cwd":""');
  });

  it("首帧即已知 blank 会话（上一轮未知）仍必须上报空串，防跨页签串台（#1028 回归）", async () => {
    okFetch();
    const ctx = {
      sessions: { list: { getSnapshot: () => listWith({ blank: true }) } },
    } as unknown as McpClientContext;
    // prevResolved=false 且 prevCwd=undefined：cwd「没变」，但仍必须发。
    // 删掉 session.ts 短路条件里的 prevResolved &&，本用例立刻打红。
    const state = makeState(undefined, false);
    const actions = makeActions();
    bindSession(ctx, state as never, actions as never);
    await new Promise((r) => setTimeout(r, 0));
    expect(state.sessionResolved).toBe(true);
    expect(fetchCalls()).toEqual([SESSION_PATH]);
    expect(fetchBodies()[0]).toContain('"cwd":""');
  });

  it("首帧未知保持安静，连续多帧仍未知才告警（#1028 隔离实测：冷启动竞态不是故障）", async () => {
    okFetch();
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    // 真正的未知：快照在，但没有 main-view 行（listWith 会补 mainView，故手写空行表）。
    let listener: (() => void) | undefined;
    const ctx = {
      sessions: {
        list: {
          getSnapshot: () => ({
            ids: ["s1"],
            byId: { s1: { id: "s1" } },
            phase: "ready",
            projectionsBySession: {},
          }),
          subscribe: (fn: () => void) => {
            listener = fn;
            return () => {
              listener = undefined;
            };
          },
        },
      },
    } as unknown as McpClientContext;
    const state = makeState(undefined, false);
    const actions = makeActions();
    bindSession(ctx, state as never, actions as never);
    await new Promise((r) => setTimeout(r, 0));
    expect(state.sessionResolved).toBe(false);
    // 首帧是官方快照尚未被 mainView 持有的竞态：每次冷启动必现，必须安静。
    expect(warn).not.toHaveBeenCalled();
    // 第二帧仍读不到 = 真失联：开口。
    listener?.();
    expect(warn).toHaveBeenCalledTimes(1);
    // 幂等闸：后续帧不得刷屏。
    listener?.();
    expect(warn).toHaveBeenCalledTimes(1);
    warn.mockRestore();
  });

  it("已解析过又读不到立即告警（#1028 失效签名，隔离实测口径）", async () => {
    okFetch();
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    let known = true;
    let listener: (() => void) | undefined;
    const ready = { phase: "ready", projectionsBySession: {} };
    const ctx = {
      sessions: {
        list: {
          getSnapshot: () =>
            known
              ? {
                  ids: ["s1"],
                  byId: { s1: { id: "s1", cwd: "/a", retainedBy: { mainView: 1 } } },
                  ...ready,
                }
              : { ids: ["s1"], byId: { s1: { id: "s1" } }, ...ready },
          subscribe: (fn: () => void) => {
            listener = fn;
            return () => {
              listener = undefined;
            };
          },
        },
      },
    } as unknown as McpClientContext;
    const state = makeState(undefined, false);
    const actions = makeActions();
    bindSession(ctx, state as never, actions as never);
    await new Promise((r) => setTimeout(r, 0));
    expect(state.sessionResolved).toBe(true);
    expect(warn).not.toHaveBeenCalled();
    // 已解析过 → 掉回未知：不靠帧数掩盖回归，立刻告警；且仍不上报 cwd:""。
    known = false;
    listener?.();
    expect(state.sessionResolved).toBe(false);
    expect(warn).toHaveBeenCalledTimes(1);
    expect(fetchBodies().at(-1)).toContain('"/a"');
    warn.mockRestore();
  });

  it("subscribe 存在时返回其 disposer（配对），缺失时返回 noop", () => {
    okFetch();
    const disposer = vi.fn();
    const subscribe = vi.fn(() => disposer);
    const ctx = {
      sessions: {
        list: {
          getSnapshot: () => listWith({ cwd: "/a" }),
          subscribe,
        },
      },
    } as unknown as McpClientContext;
    const state = makeState(undefined);
    const actions = makeActions();
    const ret = bindSession(ctx, state as never, actions as never);
    expect(subscribe).toHaveBeenCalledTimes(1);
    expect(ret).toBe(disposer);

    const ctx2 = {
      sessions: {
        list: {
          getSnapshot: () => listWith({ cwd: "/a" }),
        },
      },
    } as unknown as McpClientContext;
    const ret2 = bindSession(ctx2, makeState(undefined) as never, makeActions() as never);
    expect(typeof ret2).toBe("function");
    ret2();
  });
});

