describe("McpClientContext.effect 配对（对齐 apply 语义）", () => {
  it("label 透传且返回的 disposer 可执行清理", () => {
    let cleaned = false;
    let seenLabel: string | undefined;
    let captured: (() => () => void) | undefined;
    const ctx = {
      get: () => undefined,
      effect: (fn: () => () => void, label?: string) => {
        seenLabel = label;
        captured = fn;
      },
