// 健康摘要徽标（.dm-counts，面板头内）：摘要文案按 counts 逐档拼装，失败计数就地标红。
// 文案与标红是两件不同的事（countsSummaryText / renderCountsBadge），两条都锁：
// 删掉标红那一句只打红标红用例，文案用例照绿。
describe("健康摘要徽标：文案与失败标红", () => {
  /** 按真实 zh 文案绑 locale：标红靠 failedText 是 summary 的子串，key 形态绑不出来。 */
  function bindRealisticLocale(): void {
    bindLocale(
      {
        bind: (): ((key: string, params?: Record<string, unknown>) => string) => (key, params) => {
          const n = String(params?.n ?? "");
          if (key === "countsConnected") return `运行中 ${n}`;
          if (key === "countsConnecting") return `连接中 ${n}`;
          if (key === "countsFailed") return `失败 ${n}`;
          if (key === "countsSummary") return `共 ${n} 台 · ${String(params?.parts ?? "")}`;
          if (key === "countsSummaryOnly") return `共 ${n} 台`;
          return key;
        },
      },
      "mcpManager",
    );
  }

  // 徽标节点由 showPanel 建面板头时创建；随后 refresh 单飞复用同一次拉取把文案画上去。
  async function paintBadge(counts: Record<string, number>, serverCount: number): Promise<void> {
    const log = new FetchLog();
    restoreFetch = installFetchFake(log, {
      servers: Array.from({ length: serverCount }, (_, i) => ({ name: "s" + i })),
      counts,
      projectRoot: "/tmp/proj",
    });
    const state = createState();
    const { actions } = makeActions();
    showPanel(state, actions);
    await refresh(state, actions);
    vi.advanceTimersByTime(400);
  }

  it("三档齐全：文案按 running/connecting/failed 顺序拼接", async () => {
    bindRealisticLocale();
    await paintBadge({ connected: 2, connecting: 1, reconnecting: 2, failed: 1 }, 3);
    expect(document.querySelector(".dm-counts")?.textContent).toBe(
      "共 3 台 · 运行中 2 · 连接中 3 · 失败 1",
    );
  });

  it("connecting 与 reconnecting 合并为一段（连接中取两者之和）", async () => {
    bindRealisticLocale();
    await paintBadge({ reconnecting: 2 }, 3);
    expect(document.querySelector(".dm-counts")?.textContent).toBe("共 3 台 · 连接中 2");
  });

  it("无任何计数档位 → 退到「共 N 台」单段", async () => {
    bindRealisticLocale();
    await paintBadge({}, 3);
    expect(document.querySelector(".dm-counts")?.textContent).toBe("共 3 台");
  });

  it("缺档位按 0 读（不产生 0 值文案段）", async () => {
    bindRealisticLocale();
    await paintBadge({ connected: 0, failed: 0 }, 3);
    expect(document.querySelector(".dm-counts")?.textContent).toBe("共 3 台");
  });

  it("失败计数标红：失败段被 .dm-health-bad 拆出，其余原样可读", async () => {
    bindRealisticLocale();
    await paintBadge({ connected: 2, failed: 1 }, 3);
    const badge = document.querySelector(".dm-counts")!;
    const bad = badge.querySelectorAll(".dm-health-bad");
    expect(bad.length).toBe(1);
    expect(bad[0]!.textContent).toBe("失败 1");
    expect(badge.textContent).toBe("共 3 台 · 运行中 2 · 失败 1");
  });

  it("无失败计数 → 不产生 .dm-health-bad（不误标）", async () => {
    bindRealisticLocale();
    await paintBadge({ connected: 2, connecting: 1 }, 3);
    expect(document.querySelectorAll(".dm-health-bad").length).toBe(0);
  });

  it("面板头未建（徽标缺席）→ 静默跳过，不抛", async () => {
    bindRealisticLocale();
    const log = new FetchLog();
    restoreFetch = installFetchFake(log, {
      servers: [{ name: "a" }],
      counts: { connected: 1, failed: 1 },
      projectRoot: "/tmp/proj",
    });
    const state = createState();
    const ok = await refresh(state, makeActions().actions);
    expect(ok).toBe(true);
    expect(document.querySelector(".dm-counts")).toBeNull();
  });
});

// @vitest-environment happy-dom
/**
 * dsh-mcp-manager — 设置卡直测（P3-b/B6）。
 *
 * 守的事实（一句话）：SettingsCard 的 page 经 GET /config 读扁平 UI 5 键并经
 * POST /config 写回；summary 不发请求，page 根节点不是旧 settings list item。
 *
 * 时间纪律：act 排空 Promise（render+act 即 page mount），
 * 不用假时钟（2400ms 清提示不断）；pollUntil 不用；离线（fetch 手写假件），无落盘。
 *
 * 假件说明：fetch 是 globalThis 上的手写假函数（只记调用、按方法分流返回
 * GET 快照与 POST 回执，不实现任何服务端语义）；locale 不装配（t 回落 key 本体，
 * 故字段与按钮文案回落 key 本体）；唯一 vi 用法是 deferred 的手动 resolve（非 vi.fn 替身）。
 */
import * as React from "react";
import { act, cleanup, fireEvent, render } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { SettingsCard } from "../../src/client/settings/settings-card.tsx";
import { bindLocale } from "../../../../shared/client/i18n.js";

type FetchCall = { url: string; method: string; body: string | undefined };

let calls: FetchCall[];
let getPayload: unknown;
let postReply: () => Promise<{ ok: boolean; body: unknown }>;
let postDeferred:
  | {
      promise: Promise<{ ok: boolean; body: unknown }>;
      resolve: (v: { ok: boolean; body: unknown }) => void;
    }
  | undefined;
const realFetch = globalThis.fetch;

function okWrap(body: unknown): { ok: boolean; body: unknown } {
  return { ok: true, body };
}

function installFetch(): void {
  const fake = async (
    input: unknown,
    init?: { method?: string; body?: unknown },
  ): Promise<unknown> => {
    const url = String(input);
    const method = init?.method ?? "GET";
    const body = init?.body !== undefined ? String(init.body) : undefined;
    calls.push({ url, method, body });
    if (method === "POST") {
      if (postDeferred !== undefined) {
        const p = postDeferred.promise;
        postDeferred = undefined;
        const v = await p;
        return {
          ok: v.ok,
          status: v.ok ? 200 : 500,
          json: async (): Promise<unknown> => v.body,
        };
      }
      const v = await postReply();
      return {
        ok: v.ok,
        status: v.ok ? 200 : 500,
        json: async (): Promise<unknown> => v.body,
      };
    }
    return {
      ok: true,
      status: 200,
      json: async (): Promise<unknown> => getPayload,
    };
  };
  globalThis.fetch = fake as unknown as typeof fetch;
}

function baseCfg(): Record<string, unknown> {
  return { position: "top-right", offsetX: 8, offsetY: 8, blankY: 40, zIndexBase: 3000 };
}

function card(view: "summary" | "page" = "page", form?: unknown): React.ReactElement {
  const props: { view: "summary" | "page"; form?: unknown } =
    form === undefined ? { view } : { view, form };
  return React.createElement(SettingsCard, props);
}

/** row page 直接渲染完整表单；GET 排空后字段即可操作。 */
async function mountPage(): Promise<ReturnType<typeof render>> {
  const view = render(card("page"));
  await act(async () => {});
  return view;
}

function posts(): FetchCall[] {
  return calls.filter((c) => c.method === "POST");
}

function lastPostBody(): Record<string, unknown> {
  const p = posts();
  if (p.length === 0) throw new Error("expected at least one POST");
  return JSON.parse(String(p[p.length - 1].body)) as Record<string, unknown>;
}

beforeEach(() => {
  document.body.textContent = "";
  calls = [];
  postDeferred = undefined;
  getPayload = baseCfg();
  postReply = async () => okWrap({ ok: true });
  installFetch();
  bindLocale(
    {
      bind:
        () =>
        (key: string): string =>
          key,
    },
    "mcpManager",
  );
});

afterEach(() => {
  cleanup();
  globalThis.fetch = realFetch;
  document.body.textContent = "";
  bindLocale(
    {
      bind:
        () =>
        (key: string): string =>
          key,
    },
    "mcpManager",
  );
});

